<x-layouts.member :title="$title" :ministry-name="$settings->name" :features="$features"><section class="member-page-heading"><p>MY CALENDAR</p><h1>Events</h1><span>Your registrations, waitlists, and upcoming gatherings in one place.</span></section>@if(session('status'))<div class="workspace-notice workspace-notice-success">{{ session('status') }}</div>@endif<section class="member-event-grid">@forelse($events as $event)<article><a class="member-event-image" href="{{ route('public.events.show',$event->slug) }}" @if($event->image_url) style="background-image:linear-gradient(180deg,transparent,rgb(7 20 41 / 68%)),url('{{ $event->image_url }}')" @endif><time><b>{{ \Illuminate\Support\Carbon::parse($event->starts_at)->timezone($settings->timezone)->format('M') }}</b><strong>{{ \Illuminate\Support\Carbon::parse($event->starts_at)->timezone($settings->timezone)->format('d') }}</strong></time></a><div><span class="member-event-status">{{ str($event->registration_status)->headline() }}</span><h2>{{ $event->title }}</h2><p>{{ \Illuminate\Support\Carbon::parse($event->starts_at)->timezone($settings->timezone)->format('l, g:i A') }} · {{ $event->location ?: 'Location TBA' }}</p><div><a href="{{ route('public.events.show',$event->slug) }}">View details</a>@if(in_array($event->registration_status,['registered','waitlisted']))<form method="POST" action="{{ route('member.events.cancel',$event->id) }}">@csrf @method('DELETE')<button>Cancel registration</button></form>@endif</div></div></article>@empty<div class="member-empty-state"><x-ui.icon name="calendar" :size="24"/><strong>No events on your calendar</strong><p>Explore upcoming gatherings and register when something feels right.</p><a href="{{ route('public.events') }}">Browse events</a></div>@endforelse</section></x-layouts.member>
